arguments.file_text:
@page "/catalog"
@using sv_65e50eeb41734a2bbce2fa5e8d0b5575.Components.Catalog
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
        <button class="btn btn-link btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else
{
    <div class="d-flex catalog-layout">
        <aside class="catalog-sidebar border-end">
            <CatalogFilters Categories="_categories" OnApplyFilters="HandleApplyFilters" />
        </aside>

        <main class="catalog-main flex-grow-1 ps-3">
            @if (_loading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                    <p class="mt-2 text-muted">Loading products…</p>
                </div>
            }
            else
            {
                <CatalogToolbar SortBy="@_sortBy"
                                TotalCount="@(_result?.TotalCount ?? 0)"
                                Page="@_page"
                                PageSize="@PageSize"
                                OnSortChanged="HandleSortChanged" />

                <ProductGrid Products="@(_result?.Items ?? new())"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />

                @if (_result is not null)
                {
                    <CatalogPagination Page="@_result.Page"
                                       TotalPages="@TotalPages"
                                       OnPageChanged="HandlePageChanged" />
                }
            }
        </main>
    </div>
}

@code {
    private const int PageSize = 9;

    private List<string>? _categories;
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _page = 1;
    private bool _loading = true;
    private string? _error;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private int TotalPages => _result is null || _result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        try
        {
            _loading = true;
            _error = null;

            var categoriesTask = _categories is null
                ? ProductService.GetCategoriesAsync()
                : Task.FromResult(_categories);
            var searchTask = ProductService.SearchAsync(_filter, _sortBy, _page, PageSize);

            await Task.WhenAll(categoriesTask, searchTask);

            _categories = await categoriesTask;
            _result = await searchTask;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        _filter = filter;
        _page = 1;
        await LoadDataAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _page = 1;
        await LoadDataAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _page = page;
        await LoadDataAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder — wire up to a cart service as needed
        return Task.CompletedTask;
    }

    private async Task RetryAsync()
    {
        await LoadDataAsync();
    }
}

.catalog-layout {
    min-height: 60vh;
}

.catalog-sidebar {
    width: 25%;
    min-width: 200px;
    flex-shrink: 0;
}

.catalog-main {
    width: 75%;
}

.product-card {
    cursor: pointer;
    transition: box-shadow 0.15s ease-in-out;
}

.product-card:hover {
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.15);
}

